# Two fixes for ratings not showing on /products: coerces the
# numeric(2,1) rating column to a real number (Postgres numerics
# can come back as strings, breaking ProductMeta's typeof check),
# and adds force-dynamic to the actual page file (the revalidate/
# fetchCache exports in products.ts were inert there since Next.js
# only reads those from route files, not imported library modules).

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\lib\products.ts"), $bytes)
Write-Host "UPDATED: src\lib\products.ts" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\products\page.tsx"), $bytes)
Write-Host "UPDATED: src\app\products\page.tsx" -ForegroundColor Green

Write-Host "`nBoth files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan